package cn.zhuatech.documentai.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
/**
 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
 */
@Service public class DocumentExtractionReleaseService{/**
                                                        * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                        */
public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.documentClassificationApplied())b.add("文档分类未应用");if(!r.malwareScanPassed())b.add("文档安全扫描未通过");if(!r.piiControlsApproved())b.add("个人信息处理控制未批准");if(r.sampleAccuracy()<r.minSampleAccuracy())b.add("样本抽取准确率低于阈值");if(!r.criticalFieldsValidated())b.add("关键字段校验未通过");if(!r.humanReviewRouteReady())b.add("低置信度人工复核流程未就绪");if(!r.modelVersionRecorded())b.add("模型与模板版本未记录");if(!r.auditTrailEnabled())b.add("抽取审计轨迹未启用");if(!r.finalApprovalComplete())b.add("生产发布审批未完成");if(!b.isEmpty()){a.add("阻断生产发布并修复文档安全、质量和治理缺口");return new Assessment(Decision.BLOCKED,b,a);}if(!r.monitoringReady()||!r.rollbackReady()){if(!r.monitoringReady())a.add("配置置信度、字段错误和人工改写监控");if(!r.rollbackReady())a.add("准备模板与模型回滚版本");return new Assessment(Decision.PILOT,b,a);}a.add("批准抽取服务发布并归档样本、版本和审批证据");return new Assessment(Decision.RELEASE,b,a);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            */
public record Request(@NotBlank String templateVersion,boolean documentClassificationApplied,boolean malwareScanPassed,boolean piiControlsApproved,@DecimalMin("0")double sampleAccuracy,@DecimalMin("0")double minSampleAccuracy,boolean criticalFieldsValidated,boolean humanReviewRouteReady,boolean modelVersionRecorded,boolean auditTrailEnabled,boolean monitoringReady,boolean rollbackReady,boolean finalApprovalComplete){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 */
public record Assessment(Decision decision,List<String>blockers,List<String>actions){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       */
public enum Decision{RELEASE,PILOT,BLOCKED}}
